#!/usr/bin/env python3
"""Eyes Are the Window to the Soul — ASCII Animation Series.

Inspired by the quote, "The eyes are the window to the soul."
Built by Homesh Peter Paul.

Rotating ASCII faces release streams from their eyes, with HOMESH appearing
only during each outgoing stream. This edition uses a monochrome palette.
Animation data is embedded for self-contained playback and GIF export.
Requires Pillow; desktop playback additionally requires Python with Tk support.
"""
from pathlib import Path
import argparse
import colorsys
import base64
import io
import zlib
import time
from PIL import Image, ImageTk, ImageDraw, ImageFont, ImageOps

ROOT = Path(__file__).resolve().parent


def recolor(frame, shift):
    """Apply the fixed monochrome palette and preserve transparency."""
    rgba = frame.convert('RGBA')
    result = ImageOps.grayscale(rgba).convert('RGBA')
    result.putalpha(rgba.getchannel('A'))
    return result


def add_homesh(frame, index, total, shift=150):
    """Show HOMESH only in the outgoing eye stream.

    Hand-keyed eye positions use a normalized 400px coordinate system.
    The inscription joins the outgoing particle stream during each emission.
    """
    # HOMESH appears only during the outgoing eye stream.
    # Hand-keyed positions synchronize the lettering with the embedded frames.
    keys = [
        (0, 140, 184, 195, 1), (10, 170, 205, 195, 1),
        (18, 224, 224, 195, 1), (27, 250, 250, 195, 1),
        (40, 245, 245, 195, 1), (54, 215, 215, 195, 1),
        (65, 173, 173, 195, 1), (73, 110, 110, 195, 1),
        (81, 29, 84, 196, 1), (96, 78, 126, 195, 1),
        (109, 111, 157, 194, 1), (119, 166, 199, 195, 1),
        (127, 223, 223, 195, 1), (136, 240, 240, 195, 1),
        (150, 217, 217, 195, 1), (163, 182, 182, 195, 1),
        (173, 134, 134, 195, 1), (181, 114, 160, 195, 1),
        (190, 140, 184, 195, 1),
    ]
    t = index * 190 / max(1, total - 1)
    emitting = 19 <= t <= 73 or 123 <= t <= 173
    if not emitting:
        return frame
    # Reuse the second emission's path for both entries, scaled to each duration.
    motion_t = 123 + (t - 19) * (173 - 123) / (73 - 19) if t <= 73 else t
    for start, end in zip(keys, keys[1:]):
        if start[0] <= motion_t <= end[0]:
            blend = (motion_t - start[0]) / (end[0] - start[0])
            x1, x2, y, visibility = [a + (b-a)*blend for a,b in zip(start[1:],end[1:])]
            break
    if visibility <= .01:
        return frame
    scale = frame.width / 400
    overlay = Image.new('RGBA', frame.size)
    draw = ImageDraw.Draw(overlay)
    font = ImageFont.load_default(size=max(8, round(8 * scale)))
    text = 'HOMESH'
    box = draw.textbbox((0,0), text, font=font)
    text_width = box[2] - box[0]
    text_height = box[3] - box[1]
    alpha = round(255 * visibility)
    palette = [(255, 255, 255), (205, 205, 205), (235, 235, 235)]
    positions = ((x1 + x2) / 2,)
    for eye, x in enumerate(positions):
        left = x * scale - text_width / 2
        top = y * scale - text_height / 2 - box[1]
        for letter_index, letter in enumerate(text):
            offset = draw.textlength(text[:letter_index], font=font)
            color = palette[(letter_index + eye) % len(palette)]
            # Offset the letters along the outgoing plume.
            plume_offset = (letter_index - 2.5) * (1.4 if emitting else 0) * scale
            draw.text((left + offset, top + plume_offset), letter, font=font,
                      fill=(*color, alpha), stroke_width=1,
                      stroke_fill=(0,0,0,alpha))
    return Image.alpha_composite(frame.convert('RGBA'), overlay).convert('RGB')


def load_frames(source, shift):
    frames, delays = [], []
    with Image.open(source) as reference:
        for i in range(reference.n_frames):
            reference.seek(i)
            frame = recolor(reference, shift)
            background = Image.new('RGBA', frame.size, 'black')
            background.alpha_composite(frame)
            frames.append(add_homesh(background.convert('RGB'), i, reference.n_frames, shift))
            delays.append(reference.info.get('duration', 40))
    return frames, delays


def export_gif(frames, delays, destination):
    destination = Path(destination).expanduser().resolve()
    destination.parent.mkdir(parents=True, exist_ok=True)
    frames[0].save(destination, save_all=True, append_images=frames[1:],
                   duration=delays, loop=0, disposal=2, optimize=False)
    print(f'Saved {len(frames)} frames: {destination}')


VIDEO_SUFFIXES = {'.mp4', '.mov', '.mkv', '.webm'}


def parse_canvas(text):
    parts = text.lower().replace('×', 'x').split('x')
    if len(parts) != 2 or not all(part.strip().isdigit() for part in parts):
        raise argparse.ArgumentTypeError('expected WIDTHxHEIGHT, for example 1920x1080')
    width, height = (int(part) for part in parts)
    if width <= 0 or height <= 0 or width % 2 or height % 2:
        raise argparse.ArgumentTypeError('width and height must be positive even numbers')
    return width, height


def compose_landscape(frame, canvas):
    """Centre the square frame in a landscape canvas, letterboxed on black."""
    width, height = canvas
    scale = min(width / frame.width, height / frame.height)
    fitted = frame.resize((max(1, round(frame.width * scale)), max(1, round(frame.height * scale))),
                          Image.Resampling.LANCZOS)
    landscape = Image.new('RGB', canvas, 'black')
    landscape.paste(fitted, ((width - fitted.width) // 2, (height - fitted.height) // 2))
    return landscape


def frame_sequence(delays, fps):
    """Repeat source frames so the constant-rate output keeps the original timing."""
    step = 1000 / fps
    sequence, elapsed = [], 0.0
    for index, delay in enumerate(delays):
        elapsed += delay
        while elapsed >= step:
            sequence.append(index)
            elapsed -= step
    return sequence or [0]


def export_video(frames, delays, destination, canvas, fps):
    try:
        import imageio_ffmpeg
    except ImportError as error:
        raise SystemExit('Video export needs imageio-ffmpeg: python3 -m pip install imageio-ffmpeg') from error
    destination = Path(destination).expanduser().resolve()
    destination.parent.mkdir(parents=True, exist_ok=True)
    sequence = frame_sequence(delays, fps)
    composer = {index: compose_landscape(frames[index], canvas) for index in set(sequence)}
    writer = imageio_ffmpeg.write_frames(
        str(destination), canvas, fps=fps, codec='libx264', pix_fmt_in='rgb24',
        pix_fmt_out='yuv420p', bitrate='8M', macro_block_size=1,
        output_params=['-preset', 'medium', '-movflags', '+faststart'])
    writer.send(None)
    for index in sequence:
        writer.send(composer[index].tobytes())
    writer.close()
    print(f'Saved {len(sequence)} frames at {fps:g} fps ({canvas[0]}×{canvas[1]}): {destination}')


def play(frames, delays, size):
    import tkinter as tk
    root = tk.Tk()
    root.title('Eyes Are the Window to the Soul — Monochrome')
    root.configure(bg='black')
    photos = [ImageTk.PhotoImage(f.resize((size, size), Image.Resampling.LANCZOS))
              for f in frames]
    label = tk.Label(root, bg='black', borderwidth=0)
    label.pack()
    state = {'index': 0, 'paused': False, 'deadline': time.perf_counter()}

    def toggle(_event=None):
        state['paused'] = not state['paused']
        state['deadline'] = time.perf_counter()

    def tick():
        now = time.perf_counter()
        if not state['paused'] and now >= state['deadline']:
            i = state['index']
            label.configure(image=photos[i])
            state['deadline'] = max(state['deadline'] + delays[i] / 1000, now)
            state['index'] = (i + 1) % len(photos)
        root.after(1, tick)

    root.bind('<space>', toggle)
    root.bind('<Escape>', lambda _event: root.destroy())
    tick()
    root.mainloop()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', type=Path, help='Optional replacement GIF; defaults to embedded animation')
    parser.add_argument('--hue', type=float, default=150, help='Compatibility option; this edition uses a fixed monochrome palette')
    parser.add_argument('--size', type=int, default=800, help='Playback window size')
    parser.add_argument('--export', type=Path,
                        help='Export a looping GIF (.gif) or video (.mp4/.mov/.mkv/.webm) instead of opening a window')
    parser.add_argument('--video-size', type=parse_canvas, default=(1920, 1080), metavar='WxH',
                        help='Landscape canvas for video export (default: 1920x1080)')
    parser.add_argument('--fps', type=float, help='Video frame rate (default: taken from the frame delays)')
    args = parser.parse_args()
    if args.size <= 0:
        parser.error('--size must be positive')
    if args.fps is not None and args.fps <= 0:
        parser.error('--fps must be positive')
    source = args.source if args.source else io.BytesIO(zlib.decompress(base64.b85decode(EMBEDDED_GIF)))
    frames, delays = load_frames(source, args.hue)
    if args.export and args.export.suffix.lower() in VIDEO_SUFFIXES:
        fps = args.fps or (1000 / delays[0] if len(set(delays)) == 1 else 25.0)
        export_video(frames, delays, args.export, args.video_size, fps)
    elif args.export:
        export_gif(frames, delays, args.export)
    else:
        play(frames, delays, args.size)



